import numpy as np, math
fn='opt_angles.xyz';ls=open(fn).read().splitlines()[2:];sy=[l.split()[0] for l in ls];x=np.array([[float(v) for v in l.split()[1:4]] for l in ls])
Ir=150;Zn=151;Ctop=16;Cbot=81;P=131;H1=152;H2=153;Hb=154;Et=143
# translate
y=x-x[Ir]
# rotation axis align Zn to x
def rot_axis(axis,ang):
 axis=axis/np.linalg.norm(axis);a,b,c=axis;co=np.cos(ang);si=np.sin(ang);C=1-co
 return np.array([[co+a*a*C,a*b*C-c*si,a*c*C+b*si],[b*a*C+c*si,co+b*b*C,b*c*C-a*si],[c*a*C-b*si,c*b*C+a*si,co+c*c*C]])
v=y[Zn]/np.linalg.norm(y[Zn]);t=np.array([1.,0,0]);ax=np.cross(v,t)
if np.linalg.norm(ax)<1e-8:R=np.eye(3)
else:R=rot_axis(ax,np.arccos(np.clip(np.dot(v,t),-1,1)))
y=y@R.T
# rotate around x to put top C projection +z
u=y[Ctop];phi=np.arctan2(u[1],u[2]); # rotate angle -phi about x: y'=c y - s z? matrix
Rx=rot_axis(np.array([1.,0,0]),-phi);y=y@Rx.T
np.set_printoptions(precision=3,suppress=True)
for i,n in [(Ir,'Ir'),(Zn,'Zn'),(Ctop,'Ctop'),(Cbot,'Cbot'),(P,'P'),(H1,'H1'),(H2,'H2'),(Hb,'Hb'),(Et,'EtC')]:print(n,y[i])
with open('aligned.xyz','w') as f:
 f.write(f'{len(y)}\nAligned optimized structure\n')
 for s,p in zip(sy,y):f.write(f'{s:2s} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
